+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.sidenav.SideNav;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Autowired
+    private VetRepository vetRepository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansLinkOpensTheVetListWithoutAuthentication() {
+        navigate(WelcomeView.class);
+
+        // No authentication is performed, covering BR-003 (Anonymous Access).
+        test(find(SideNav.class).single()).clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertDoesNotThrow(() -> find(Grid.class).single(), "Expected the veterinarians grid");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsEveryVetWithNamesAndSpecialties() {
+        navigate(VetsView.class);
+
+        GridTester<Grid<Object>, Object> grid = grid();
+        assertEquals(6, grid.size());
+        assertEquals("First Name", grid.getHeaderCell(0));
+        assertEquals("Last Name", grid.getHeaderCell(1));
+        assertEquals("Specialties", grid.getHeaderCell(2));
+
+        int carter = rowOf(grid, "Carter");
+        assertEquals("James", grid.getCellText(carter, 0));
+        assertEquals("none", grid.getCellText(carter, 2));
+        assertEquals("radiology", grid.getCellText(rowOf(grid, "Leary"), 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetsView.class);
+
+        GridTester<Grid<Object>, Object> grid = grid();
+        // Linda Douglas was assigned surgery before dentistry.
+        assertEquals("dentistry, surgery", grid.getCellText(rowOf(grid, "Douglas"), 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsVetsLazilyFromTheBackend() {
+        dsl.batch(IntStream.rangeClosed(1, 200)
+                        .mapToObj(i -> dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                                .values("Vet", "Zz%03d".formatted(i)))
+                        .toList())
+                .execute();
+
+        navigate(VetsView.class);
+
+        Grid<?> grid = find(Grid.class).single();
+        assertFalse(grid.getDataProvider().isInMemory(), "Expected a callback data provider, not an in-memory list");
+        assertEquals(206, grid().size(), "Expected every vet to be reachable by scrolling");
+        assertEquals(50, vetRepository.findPage(100, 50).count(), "Expected one page, not the whole directory");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, grid().size());
+    }
+
+    @SuppressWarnings("unchecked")
+    private GridTester<Grid<Object>, Object> grid() {
+        return test(find(Grid.class).single());
+    }
+
+    private static int rowOf(GridTester<Grid<Object>, Object> grid, String lastName) {
+        return IntStream.range(0, grid.size())
+                .filter(row -> grid.getCellText(row, 1).equals(lastName))
+                .findFirst()
+                .orElseThrow(() -> new AssertionError("No vet with last name " + lastName));
+    }
+}
